(8, 835, 'Thẻ Phi long', 'Dùng tốc độ cực nhanh để tiếp cận và hạ gục mục tiêu, Phi long cũng có sở thích hơi lạ là khi bay luôn mở to miệng để đón gió', 7474, 2, 120, 0, 8, -1, -1, -1, -1, '[\r\n{\"param\":1,\"active_card\":0,\"id\":103},\r\n{\"param\":1,\"active_card\":1,\"id\":77},\r\n{\"param\":1,\"active_card\":2,\"id\":50},\r\n{\"param\":1,\"active_card\":3,\"id\":103},\r\n{\"param\":1,\"active_card\":4,\"id\":77},\r\n{\"param\":1,\"active_card\":5,\"id\":50}\r\n]', -1),
(9, 836, 'Thẻ Quỷ bay', 'Sở trường tấn công chớp choáng kẻ thù, nhưng đâu ai ngờ Quỷ bay lại có bệnh sợ độ cao', 7475, 2, 120, 0, 9, -1, -1, -1, -1, '[\r\n{\"param\":1,\"active_card\":0,\"id\":103},\r\n{\"param\":1,\"active_card\":1,\"id\":77},\r\n{\"param\":1,\"active_card\":2,\"id\":50},\r\n{\"param\":1,\"active_card\":3,\"id\":103},\r\n{\"param\":1,\"active_card\":4,\"id\":77},\r\n{\"param\":1,\"active_card\":5,\"id\":50}\r\n]', -1),
(10, 837, 'Thẻ Lính độc nhãn', 'Người ta nuôi quân lính dùng trong 1 giờ, Lính độc nhãn thì không dùng được 5 phút', 7476, 3, 120, 0, 34, -1, -1, -1, -1, '[\r\n{\"param\":1,\"active_card\":0,\"id\":103},\r\n{\"param\":1,\"active_card\":1,\"id\":77},\r\n{\"param\":1,\"active_card\":2,\"id\":50},\r\n{\"param\":1,\"active_card\":3,\"id\":103},\r\n{\"param\":1,\"active_card\":4,\"id\":77},\r\n{\"param\":1,\"active_card\":5,\"id\":50}\r\n]', -1),
(11, 838, 'Thẻ Lính độc nhãn', 'Người ta nuôi quân lính dùng trong 1 giờ, Lính độc nhãn thì không dùng được 5 phút', 7477, 3, 120, 0, 35, -1, -1, -1, -1, '[\r\n{\"param\":1,\"active_card\":0,\"id\":103},\r\n{\"param\":1,\"active_card\":1,\"id\":77},\r\n{\"param\":1,\"active_card\":2,\"id\":50},\r\n{\"param\":1,\"active_card\":3,\"id\":103},\r\n{\"param\":1,\"active_card\":4,\"id\":77},\r\n{\"param\":1,\"active_card\":5,\"id\":50}\r\n]', -1),
(12, 839, 'Thẻ Sói xám', 'Được lính độc nhãn thuần hóa và cho giữ nhà như cún con, sở thích của chúng là được chơi trò nhặt bóng', 7478, 3, 120, 0, 36, -1, -1, -1, -1, '[\r\n{\"param\":1,\"active_card\":0,\"id\":103},\r\n{\"param\":1,\"active_card\":1,\"id\":77},\r\n{\"param\":1,\"active_card\":2,\"id\":50},\r\n{\"param\":1,\"active_card\":3,\"id\":103},\r\n{\"param\":1,\"active_card\":4,\"id\":77},\r\n{\"param\":1,\"active_card\":5,\"id\":50}\r\n]', -1),
(13, 840, 'Thẻ Trung úy Trắng', 'Thân hình hơi béo so với tiêu chuẩn chung, luôn đeo chiếc khăn quàng đỏ, thường hay mơ mộng làm thơ', 7480, 4, 120, 1, -1, 141, 142, 143, -1, '[\r\n{\"param\":1,\"active_card\":0,\"id\":103},\r\n{\"param\":1,\"active_card\":1,\"id\":77},\r\n{\"param\":1,\"active_card\":2,\"id\":50},\r\n{\"param\":1,\"active_card\":3,\"id\":103},\r\n{\"param\":1,\"active_card\":4,\"id\":77},\r\n{\"param\":1,\"active_card\":5,\"id\":50}\r\n]', -1),
(14, 841, 'Thẻ Ninja Áo Tím', 'Ninja với nhiều tài năng để trở thành sát thủ, nhưng kỹ thuật ẩn thân lại không có, nên không thể trở thành sát thủ', 7481, 4, 120, 1, -1, 123, 124, 125, -1, '[\r\n{\"param\":1,\"active_card\":0,\"id\":103},\r\n{\"param\":1,\"active_card\":1,\"id\":77},\r\n{\"param\":1,\"active_card\":2,\"id\":50},\r\n{\"param\":1,\"active_card\":3,\"id\":103},\r\n{\"param\":1,\"active_card\":4,\"id\":77},\r\n{\"param\":1,\"active_card\":5,\"id\":50}\r\n]', -1),
(15, 842, 'Thẻ Trung úy Xanh Lơ', 'Có siêu năng lực thôi miên nhưng cực kỳ sợ chuột', 7479, 4, 120, 1, -1, 135, 136, 137, -1, '[\r\n{\"param\":1,\"active_card\":0,\"id\":103},\r\n{\"param\":1,\"active_card\":1,\"id\":77},\r\n{\"param\":1,\"active_card\":2,\"id\":50},\r\n{\"param\":1,\"active_card\":3,\"id\":103},\r\n{\"param\":1,\"active_card\":4,\"id\":77},\r\n{\"param\":1,\"active_card\":5,\"id\":50}\r\n]', -1),
(16, 859, 'Thẻ Độc Nhãn', 'Đầu não của Red Ribbon. Bị chột một mắt. Lúc nhỏ bị mọi người chê là \'Thằng lùn\'', 1568, 5, 120, 1, -1, 144, 145, 146, -1, '[\r\n  { \"param\": 20,  \"active_card\": 0,  \"id\": 103 },\r\n  { \"param\": 20,  \"active_card\": 1,  \"id\": 77 },\r\n  { \"param\": 10,  \"active_card\": 2,  \"id\": 50 },\r\n  { \"param\": 20,  \"active_card\": 3,  \"id\": 103 },\r\n  { \"param\": 20,  \"active_card\": 4,  \"id\": 77 },\r\n  { \"param\": 10,  \"active_card\": 5,  \"id\": 50 },\r\n  { \"param\": 30,  \"active_card\": 6,  \"id\": 103 },\r\n  { \"param\": 30,  \"active_card\": 7,  \"id\": 77 },\r\n  { \"param\": 20,  \"active_card\": 8,  \"id\": 50 }\r\n]', -1),
(17, 956, 'Thẻ Đội trưởng Vàng', 'Đội trưởng Vàng là một con hổ hình người chắc nịch có cơ thể được bao phủ bởi bộ lông màu vàng, Goku đã đấm hắn ra khỏi máy bay của mình khi đang ở giữa không trung.', 8935, 5, 120, 1, -1, 994, 995, 996, -1, '[\r\n  { \"param\": 20,  \"active_card\": 0,  \"id\": 103 },\r\n  { \"param\": 20,  \"active_card\": 1,  \"id\": 77 },\r\n  { \"param\": 10,  \"active_card\": 2,  \"id\": 50 },\r\n  { \"param\": 20,  \"active_card\": 3,  \"id\": 103 },\r\n  { \"param\": 20,  \"active_card\": 4,  \"id\": 77 },\r\n  { \"param\": 10,  \"active_card\": 5,  \"id\": 50 },\r\n  { \"param\": 30,  \"active_card\": 6,  \"id\": 103 },\r\n  { \"param\": 30,  \"active_card\": 7,  \"id\": 77 },\r\n  { \"param\": 20,  \"active_card\": 8,  \"id\": 50 }\r\n]', -1),
(18, 1257, 'Mảnh Hutao', 'Khả năng tự hồi phục sức khỏe khi sử dụng kỹ năng Elemental', 12640, 5, 120, 1, -1, 1351, 1352, 1353, -1, '[\r\n  { \"param\": 20,  \"active_card\": 0,  \"id\": 103 },\r\n  { \"param\": 20,  \"active_card\": 1,  \"id\": 77 },\r\n  { \"param\": 10,  \"active_card\": 2,  \"id\": 50 },\r\n  { \"param\": 20,  \"active_card\": 3,  \"id\": 103 },\r\n  { \"param\": 20,  \"active_card\": 4,  \"id\": 77 },\r\n  { \"param\": 10,  \"active_card\": 5,  \"id\": 50 },\r\n  { \"param\": 30,  \"active_card\": 6,  \"id\": 103 },\r\n  { \"param\": 30,  \"active_card\": 7,  \"id\": 77 },\r\n  { \"param\": 20,  \"active_card\": 8,  \"id\": 50 }\r\n]', -1),
(19, 1258, 'Mảnh Xiao', 'Là một Adeptus, một loài sinh vật siêu nhiên có nguồn gốc từ Liyue, và được biết đến với biệt danh \"Con Rồng Đỏ\" hay \"Vệ Sĩ Trời Đêm\"', 12680, 5, 120, 1, -1, 1354, 1355, 1356, -1, '[\r\n  { \"param\": 20,  \"active_card\": 0,  \"id\": 103 },\r\n  { \"param\": 20,  \"active_card\": 1,  \"id\": 77 },\r\n  { \"param\": 10,  \"active_card\": 2,  \"id\": 50 },\r\n  { \"param\": 20,  \"active_card\": 3,  \"id\": 103 },\r\n  { \"param\": 20,  \"active_card\": 4,  \"id\": 77 },\r\n  { \"param\": 10,  \"active_card\": 5,  \"id\": 50 },\r\n  { \"param\": 30,  \"active_card\": 6,  \"id\": 103 },\r\n  { \"param\": 30,  \"active_card\": 7,  \"id\": 77 },\r\n  { \"param\": 20,  \"active_card\": 8,  \"id\": 50 }\r\n]', -1),
