CREATE TABLE `consignment_shop` (
  `id` int(11) NOT NULL,
  `consignor_id` int(11) NOT NULL,
  `tab` int(11) NOT NULL,
  `item_id` int(11) NOT NULL,
  `gold` int(11) NOT NULL,
  `gem` int(11) NOT NULL,
