CREATE TABLE `gift_codes` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `type` tinyint(4) NOT NULL COMMENT '0: For personal, 1: For everyone',
  `code` varchar(255) NOT NULL,
  `gold` int(11) NOT NULL DEFAULT 0,
  `gem` int(11) NOT NULL DEFAULT 0,
  `ruby` int(11) NOT NULL DEFAULT 0,
  `items` longtext DEFAULT NULL,
  `status` tinyint(4) NOT NULL COMMENT '0: Inactive, 1: Active, 2: Expired',
  `active` int(11) NOT NULL DEFAULT 0 COMMENT '0: Kh?´ng y?ªu cáº§u k?­ch hoáº¡t , 1 : y?ªu cáº§u k?­ch hoáº¡t',
  `expires_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

