INSERT INTO `notifications` (`id`, `title`, `content`) VALUES
(1, 'Thông tin Săn đệ', 'nrosky.com'),
(2, 'Giải đáp thắc mắc về Game!', 'Bạn có thắc mắc về Game? Tui sẽ giải đáp!!\r\n - Đồ thần : up Cold hoặc săn Boss\r\n - Đồ Huỷ diệt : Săn boss Hủy Diệt hoặc mua trên Bill ở Kaio\r\n - Thức ăn : Mang 5 món thần linh qua Tương lai up hoặc Cold\r\n - Mảnh thiên sứ : mang 5 món Huỷ diệt qua Hành tinh ngục tù (gặp Osin ở Hành tinh Bill)\r\n - Đồ Thiên sứ : Gặp Whis ở Hành tinh Bill có mọi thông tin\r\n - Pha lê hoá được Cải trang, Giáp luyện tập và Trang bị\r\n - 6 ô cuối hành trang lần lượt là : Pet, Danh hiệu (vp đeo lưng), Thú cưỡi, Linh thú, Chân mệnh, Sách tuyệt kĩ'),
(3, 'CÁC LỆNH CHO MEMBER', 'tt : Hiện thông tin Bản thân, Đồ mặc');

